-- Migration: exercise library from beach tennis e-book
CREATE TABLE IF NOT EXISTS exercises (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL,
  category TEXT NOT NULL,
  video_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_exercises_category ON exercises(category);

DROP TRIGGER IF EXISTS tr_exercises_updated ON exercises;
CREATE TRIGGER tr_exercises_updated BEFORE UPDATE ON exercises FOR EACH ROW EXECUTE FUNCTION update_updated_at();

ON CONFLICT (name) DO UPDATE SET
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  video_url = EXCLUDED.video_url,
  updated_at = NOW();